import secrets

from django.db import migrations, models
from django.utils import timezone


def carry_over_uploaded_covers(apps, schema_editor):
    """Move covers uploaded through the old file field into the database.

    The old files lived in the media folder, which production doesn't serve,
    so they never showed. Any that can still be read are kept; the rest fall
    back to the automatic picture.
    """
    from api.utils.pictures import to_webp

    Post = apps.get_model("blog", "Post")
    for post in Post.objects.exclude(cover_image="").exclude(cover_image__isnull=True):
        try:
            with post.cover_image.open("rb") as upload:
                data, width, height = to_webp(upload)
        except Exception:
            continue
        post.cover_source = "custom"
        post.cover_data = data
        post.cover_width, post.cover_height = width, height
        post.cover_version = secrets.token_hex(6)
        post.cover_updated_at = timezone.now()
        post.save(update_fields=[
            "cover_source", "cover_data", "cover_width", "cover_height", "cover_version", "cover_updated_at",
        ])


